css:
.fieldset {
  --main-color: #4a4d96;
  border: 2px var(--main-color) solid;
  font-size: 0.75rem;
  border-radius: 5px;
}
legend {
  color: var(--main-color);
}
.fieldset input[type="text"] {
  /* reset the field */
  outline: none;
  border: none;
  background: transparent;

  padding: 0 10px 10px 10px;
  font-size: 0.75rem;
}
